-- ====================================================================
-- 20261111000001_business_and_application_schema.sql
-- ====================================================================
-- Permitayo, Phase 3: business profiles and permit applications (schema).
-- Tables: reference_counters, permit_types, business_establishments,
--         permit_applications, application_status_history.
-- Security (grants, RLS, guard triggers, RPCs) is in the next migration.
--
-- Existing Phase 2 tables are not changed. owner_id / applicant_id reference
-- public.profiles(id), which is the auth user's id.

-- ---------------------------------------------------------------------------
-- reference_counters: per-prefix, per-year counters for public reference
-- numbers (BUS-2026-000001, PTY-2026-000001). Only definer functions touch it.
-- ---------------------------------------------------------------------------
create table public.reference_counters (
  prefix text not null
    constraint reference_counters_prefix_format check (prefix ~ '^[A-Z]{2,5}$'),
  year integer not null
    constraint reference_counters_year_range check (year between 2000 and 2999),
  last_value bigint not null default 0
    constraint reference_counters_last_value_positive check (last_value >= 0),
  primary key (prefix, year)
);

comment on table public.reference_counters is
  'Server-side counters for public reference numbers. Not readable or writable by API roles.';

-- Returns the next reference for a prefix and year, e.g. PTY-2026-000001.
-- The INSERT ... ON CONFLICT DO UPDATE takes a row lock, so concurrent callers
-- are serialised and can never receive the same number. A rolled-back
-- transaction also rolls back its increment, so numbers are not skipped.
create or replace function public.next_reference_number(p_prefix text, p_year integer)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_value bigint;
begin
  insert into public.reference_counters as rc (prefix, year, last_value)
  values (p_prefix, p_year, 1)
  on conflict (prefix, year)
  do update set last_value = rc.last_value + 1
  returning rc.last_value into v_value;

  return p_prefix || '-' || p_year::text || '-'
    || case when v_value < 1000000 then lpad(v_value::text, 6, '0') else v_value::text end;
end;
$$;

-- Current year in Philippine time (used for reference numbers).
create or replace function public.manila_year()
returns integer
language sql
stable
set search_path = ''
as $$
  select extract(year from (now() at time zone 'Asia/Manila'))::integer
$$;

-- ---------------------------------------------------------------------------
-- permit_types: configurable application types
-- ---------------------------------------------------------------------------
create table public.permit_types (
  id uuid primary key default gen_random_uuid(),
  name text not null
    constraint permit_types_name_length check (char_length(btrim(name)) between 2 and 120),
  description text
    constraint permit_types_description_length check (description is null or char_length(description) <= 1000),
  application_code text not null
    constraint permit_types_code_format check (application_code ~ '^[A-Z0-9_]{2,24}$'),
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint permit_types_code_key unique (application_code)
);

create unique index permit_types_name_lower_key on public.permit_types (lower(name));

create trigger permit_types_set_updated_at
  before update on public.permit_types
  for each row execute function public.set_updated_at();

comment on table public.permit_types is
  'Application types. Managed by administrators. No municipal procedure or eligibility rule is encoded here.';

-- ---------------------------------------------------------------------------
-- business_establishments: applicant-managed business profiles
-- A profile here is NOT an official government registration.
-- ---------------------------------------------------------------------------
create table public.business_establishments (
  id uuid primary key default gen_random_uuid(),
  -- Restrict: a profile with business records cannot be silently removed.
  owner_id uuid not null default auth.uid() references public.profiles (id) on delete restrict,
  -- Assigned by trigger (BUS-YYYY-NNNNNN). Never accepted from the client.
  business_reference_number text not null,

  -- Basic information
  registered_business_name text not null
    constraint business_name_length check (char_length(btrim(registered_business_name)) between 2 and 200),
  trade_name text
    constraint business_trade_name_length check (trade_name is null or char_length(trade_name) <= 200),
  business_description text
    constraint business_description_length check (business_description is null or char_length(business_description) <= 1000),
  business_type text not null
    constraint business_type_length check (char_length(btrim(business_type)) between 2 and 120),
  ownership_type text not null
    constraint business_ownership_type_allowed check (
      ownership_type in ('sole_proprietorship', 'partnership', 'corporation', 'cooperative', 'other')
    ),
  business_category text not null
    constraint business_category_length check (char_length(btrim(business_category)) between 2 and 120),
  business_email text
    constraint business_email_format check (
      business_email is null or (char_length(business_email) <= 254 and business_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$')
    ),
  business_contact_number text not null
    constraint business_contact_format check (business_contact_number ~ '^(\+63|0)[2-9][0-9]{7,9}$'),

  -- Address (defaults to Rosario, Batangas but stays configurable)
  province text not null default 'Batangas'
    constraint business_province_length check (char_length(btrim(province)) between 2 and 80),
  municipality text not null default 'Rosario'
    constraint business_municipality_length check (char_length(btrim(municipality)) between 2 and 80),
  barangay text not null
    constraint business_barangay_length check (char_length(btrim(barangay)) between 2 and 80),
  street_address text
    constraint business_street_length check (street_address is null or char_length(street_address) <= 200),
  zip_code text not null
    constraint business_zip_format check (zip_code ~ '^[0-9]{4}$'),

  -- Owner
  owner_full_name text not null
    constraint business_owner_name_length check (char_length(btrim(owner_full_name)) between 2 and 120),
  owner_email text
    constraint business_owner_email_format check (
      owner_email is null or (char_length(owner_email) <= 254 and owner_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$')
    ),
  owner_contact_number text not null
    constraint business_owner_contact_format check (owner_contact_number ~ '^(\+63|0)[2-9][0-9]{7,9}$'),

  -- Operation
  nature_of_business text not null
    constraint business_nature_length check (char_length(btrim(nature_of_business)) between 2 and 300),
  employee_count integer not null default 0
    constraint business_employee_count_range check (employee_count between 0 and 1000000),
  estimated_capital numeric(15, 2)
    constraint business_capital_range check (estimated_capital is null or estimated_capital between 0 and 9999999999999.99),
  establishment_status text not null
    constraint business_establishment_status_allowed check (
      establishment_status in ('not_yet_operating', 'operating', 'temporarily_closed', 'permanently_closed')
    ),
  date_established date
    constraint business_date_established_range check (date_established is null or date_established >= date '1900-01-01'),

  -- Record status of this Permitayo profile (not a government status)
  record_status text not null default 'pending_verification'
    constraint business_record_status_allowed check (record_status in ('pending_verification', 'active', 'inactive')),

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint business_reference_number_key unique (business_reference_number)
);

create index business_owner_idx on public.business_establishments (owner_id, created_at desc);
create index business_record_status_idx on public.business_establishments (record_status);
create index business_name_lower_idx on public.business_establishments (lower(registered_business_name));
create index business_created_at_idx on public.business_establishments (created_at desc);

create trigger business_establishments_set_updated_at
  before update on public.business_establishments
  for each row execute function public.set_updated_at();

-- Always assign the reference number on the server, ignoring any supplied value.
create or replace function public.assign_business_reference()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.business_reference_number := public.next_reference_number('BUS', public.manila_year());
  return new;
end;
$$;

create trigger business_establishments_assign_reference
  before insert on public.business_establishments
  for each row execute function public.assign_business_reference();

comment on table public.business_establishments is
  'Business profiles entered by applicants. A profile is not an official government registration.';

-- ---------------------------------------------------------------------------
-- permit_applications
-- ---------------------------------------------------------------------------
create table public.permit_applications (
  id uuid primary key default gen_random_uuid(),
  -- Public reference (PTY-YYYY-NNNNNN). Null while the application is a draft.
  reference_number text,
  applicant_id uuid not null default auth.uid() references public.profiles (id) on delete restrict,
  business_id uuid not null references public.business_establishments (id) on delete restrict,
  permit_type_id uuid not null references public.permit_types (id) on delete restrict,
  application_status text not null default 'draft'
    constraint permit_applications_status_allowed check (application_status in ('draft', 'submitted', 'cancelled')),

  -- Application details (prefilled from the business profile, editable while draft)
  business_name text
    constraint permit_applications_business_name_length check (business_name is null or char_length(business_name) <= 200),
  business_address text
    constraint permit_applications_business_address_length check (business_address is null or char_length(business_address) <= 400),
  nature_of_business text
    constraint permit_applications_nature_length check (nature_of_business is null or char_length(nature_of_business) <= 300),
  business_category text
    constraint permit_applications_category_length check (business_category is null or char_length(business_category) <= 120),
  applicant_remarks text
    constraint permit_applications_remarks_length check (applicant_remarks is null or char_length(applicant_remarks) <= 1000),

  -- Frozen copy of the applicant and business profile at submission time.
  submission_snapshot jsonb,

  cancellation_reason text
    constraint permit_applications_cancel_reason_length check (cancellation_reason is null or char_length(cancellation_reason) <= 500),
  cancelled_by uuid references public.profiles (id) on delete set null,
  submitted_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint permit_applications_reference_key unique (reference_number),
  constraint permit_applications_reference_format check (
    reference_number is null or reference_number ~ '^PTY-[0-9]{4}-[0-9]{6,}$'
  ),
  -- Status / timestamp consistency.
  constraint permit_applications_state_consistency check (
    (application_status = 'draft' and reference_number is null and submitted_at is null and cancelled_at is null)
    or (application_status = 'submitted' and reference_number is not null and submitted_at is not null and cancelled_at is null)
    or (application_status = 'cancelled' and cancelled_at is not null)
  )
);

create index permit_applications_applicant_idx on public.permit_applications (applicant_id, created_at desc);
create index permit_applications_business_idx on public.permit_applications (business_id, created_at desc);
create index permit_applications_type_idx on public.permit_applications (permit_type_id);
create index permit_applications_status_idx on public.permit_applications (application_status, submitted_at desc);
create index permit_applications_business_name_lower_idx on public.permit_applications (lower(business_name));

create trigger permit_applications_set_updated_at
  before update on public.permit_applications
  for each row execute function public.set_updated_at();

comment on table public.permit_applications is
  'Business permit applications. Status, reference number and timestamps change only through definer functions.';

-- ---------------------------------------------------------------------------
-- application_status_history: append-only status trail (written by trigger)
-- ---------------------------------------------------------------------------
create table public.application_status_history (
  id uuid primary key default gen_random_uuid(),
  -- Drafts can be deleted by their owner; their history goes with them.
  -- Non-draft applications cannot be deleted (see guard trigger).
  application_id uuid not null references public.permit_applications (id) on delete cascade,
  previous_status text,
  new_status text not null,
  changed_by uuid references public.profiles (id) on delete set null,
  remarks text
    constraint application_status_history_remarks_length check (remarks is null or char_length(remarks) <= 500),
  created_at timestamptz not null default now()
);

create index application_status_history_application_idx
  on public.application_status_history (application_id, created_at);

-- ====================================================================
-- 20261111000002_business_and_application_security.sql
-- ====================================================================
-- Permitayo, Phase 3: security model for business profiles and applications.
--
-- Same principles as Phase 2:
--   1. Revoke everything, then grant back the minimum (column-level where possible).
--   2. RLS on every table. Applicants see only their own rows. BPLO personnel and
--      administrators can read business profiles and NON-draft applications.
--   3. Ownership (owner_id, applicant_id), reference numbers, statuses and
--      timestamps are never writable by API roles. Status changes happen only in
--      SECURITY DEFINER functions that re-check the caller with auth.uid().
--   4. Guard triggers repeat the column rules as a second line of defence.
--   5. Every status change is written to application_status_history by a trigger,
--      and significant events are written to audit_logs (no personal values).

-- ---------------------------------------------------------------------------
-- Guard triggers (defence in depth)
-- ---------------------------------------------------------------------------
create or replace function public.guard_business_protected_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user in ('anon', 'authenticated')
     and (
       new.id is distinct from old.id
       or new.owner_id is distinct from old.owner_id
       or new.business_reference_number is distinct from old.business_reference_number
       or new.record_status is distinct from old.record_status
       or new.created_at is distinct from old.created_at
     )
  then
    raise exception 'This business field cannot be changed directly.' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger business_establishments_guard_protected_columns
  before update on public.business_establishments
  for each row execute function public.guard_business_protected_columns();

create or replace function public.guard_application_insert()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user in ('anon', 'authenticated') then
    -- New applications from the API always start as an unreferenced draft owned by the caller.
    if new.applicant_id is distinct from (select auth.uid())
       or new.application_status <> 'draft'
       or new.reference_number is not null
       or new.submitted_at is not null
       or new.cancelled_at is not null
       or new.cancelled_by is not null
       or new.cancellation_reason is not null
       or new.submission_snapshot is not null
    then
      raise exception 'Applications must be created as drafts by their owner.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create trigger permit_applications_guard_insert
  before insert on public.permit_applications
  for each row execute function public.guard_application_insert();

create or replace function public.guard_application_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user in ('anon', 'authenticated') then
    if old.application_status <> 'draft' then
      raise exception 'Submitted or cancelled applications cannot be changed directly.' using errcode = '42501';
    end if;
    if new.id is distinct from old.id
       or new.applicant_id is distinct from old.applicant_id
       or new.application_status is distinct from old.application_status
       or new.reference_number is distinct from old.reference_number
       or new.submitted_at is distinct from old.submitted_at
       or new.cancelled_at is distinct from old.cancelled_at
       or new.cancelled_by is distinct from old.cancelled_by
       or new.cancellation_reason is distinct from old.cancellation_reason
       or new.submission_snapshot is distinct from old.submission_snapshot
       or new.created_at is distinct from old.created_at
    then
      raise exception 'This application field cannot be changed directly.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create trigger permit_applications_guard_update
  before update on public.permit_applications
  for each row execute function public.guard_application_update();

-- Only drafts may ever be deleted, by anyone. Submitted and cancelled records are kept.
create or replace function public.guard_application_delete()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.application_status <> 'draft' then
    raise exception 'Only draft applications can be deleted. Submitted records are preserved.' using errcode = '42501';
  end if;
  return old;
end;
$$;

create trigger permit_applications_guard_delete
  before delete on public.permit_applications
  for each row execute function public.guard_application_delete();

-- History rows are append-only for everyone (cascade from a draft delete is allowed).
create or replace function public.guard_status_history_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'Status history cannot be changed.' using errcode = '42501';
end;
$$;

create trigger application_status_history_no_update
  before update on public.application_status_history
  for each row execute function public.guard_status_history_update();

-- ---------------------------------------------------------------------------
-- Status history and audit triggers
-- ---------------------------------------------------------------------------
create or replace function public.record_application_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_remarks text := nullif(btrim(coalesce(current_setting('permitayo.status_remarks', true), '')), '');
begin
  if tg_op = 'INSERT' then
    insert into public.application_status_history (application_id, previous_status, new_status, changed_by, remarks)
    values (new.id, null, new.application_status, coalesce(v_actor, new.applicant_id), 'Draft created.');
    perform public.write_audit_log(coalesce(v_actor, new.applicant_id), 'application.created', 'permit_application', new.id,
      'Draft application created.');
  elsif new.application_status is distinct from old.application_status then
    insert into public.application_status_history (application_id, previous_status, new_status, changed_by, remarks)
    values (new.id, old.application_status, new.application_status, v_actor, left(v_remarks, 500));
  end if;
  return new;
end;
$$;

create trigger permit_applications_record_status
  after insert or update on public.permit_applications
  for each row execute function public.record_application_status();

create or replace function public.audit_business_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
begin
  if tg_op = 'INSERT' then
    perform public.write_audit_log(coalesce(v_actor, new.owner_id), 'business.created', 'business', new.id,
      'Business profile created: ' || new.business_reference_number || '.');
  elsif new.record_status is distinct from old.record_status then
    perform public.write_audit_log(v_actor, 'business.status_changed', 'business', new.id,
      'Business profile ' || new.business_reference_number || ' record status changed from '
      || old.record_status || ' to ' || new.record_status || '.');
  else
    perform public.write_audit_log(v_actor, 'business.updated', 'business', new.id,
      'Business profile updated: ' || new.business_reference_number || '.');
  end if;
  return new;
end;
$$;

create trigger business_establishments_audit_change
  after insert or update on public.business_establishments
  for each row execute function public.audit_business_change();

create or replace function public.audit_application_draft_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.write_audit_log((select auth.uid()), 'application.draft_deleted', 'permit_application', old.id,
    'Draft application deleted by its owner.');
  return old;
end;
$$;

create trigger permit_applications_audit_delete
  after delete on public.permit_applications
  for each row execute function public.audit_application_draft_delete();

create or replace function public.audit_permit_type_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
begin
  if tg_op = 'INSERT' then
    perform public.write_audit_log(v_actor, 'permit_type.created', 'permit_type', new.id,
      'Permit type created: ' || new.application_code || '.');
  elsif new.is_active is distinct from old.is_active then
    perform public.write_audit_log(v_actor,
      case when new.is_active then 'permit_type.activated' else 'permit_type.deactivated' end,
      'permit_type', new.id,
      'Permit type ' || new.application_code || case when new.is_active then ' activated.' else ' deactivated.' end);
  else
    perform public.write_audit_log(v_actor, 'permit_type.updated', 'permit_type', new.id,
      'Permit type details updated: ' || new.application_code || '.');
  end if;
  return new;
end;
$$;

create trigger permit_types_audit_change
  after insert or update on public.permit_types
  for each row execute function public.audit_permit_type_change();

-- ---------------------------------------------------------------------------
-- RPCs (each re-checks the caller inside the database)
-- ---------------------------------------------------------------------------

-- Submit a draft. Assigns the PTY-YYYY-NNNNNN reference on the server, freezes a
-- snapshot of the applicant and business details, and records the status change.
create or replace function public.submit_permit_application(p_application uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_app public.permit_applications%rowtype;
  v_business public.business_establishments%rowtype;
  v_type public.permit_types%rowtype;
  v_applicant public.profiles%rowtype;
  v_reference text;
begin
  if v_actor is null or public.current_app_role() is distinct from 'applicant' then
    raise exception 'Only applicants can submit applications.' using errcode = '42501';
  end if;

  select * into v_app from public.permit_applications where id = p_application for update;
  -- Same message whether it does not exist or belongs to someone else.
  if not found or v_app.applicant_id <> v_actor then
    raise exception 'Application not found.' using errcode = 'P0002';
  end if;
  if v_app.application_status <> 'draft' then
    raise exception 'Only draft applications can be submitted.';
  end if;

  select * into v_business from public.business_establishments where id = v_app.business_id;
  if not found or v_business.owner_id <> v_actor then
    raise exception 'The selected business profile is not yours.' using errcode = '42501';
  end if;
  if v_business.record_status = 'inactive' then
    raise exception 'The selected business profile is inactive.';
  end if;

  select * into v_type from public.permit_types where id = v_app.permit_type_id;
  if not found or not v_type.is_active then
    raise exception 'The selected application type is not available.';
  end if;

  if coalesce(btrim(v_app.business_name), '') = ''
     or coalesce(btrim(v_app.business_address), '') = ''
     or coalesce(btrim(v_app.nature_of_business), '') = ''
     or coalesce(btrim(v_app.business_category), '') = '' then
    raise exception 'Complete the business name, address, nature of business and category before submitting.';
  end if;

  select * into v_applicant from public.profiles where id = v_actor;

  v_reference := public.next_reference_number('PTY', public.manila_year());

  perform set_config('permitayo.status_remarks', 'Application submitted by the applicant.', true);

  update public.permit_applications
  set application_status = 'submitted',
      reference_number = v_reference,
      submitted_at = now(),
      submission_snapshot = jsonb_build_object(
        'applicant', jsonb_build_object(
          'full_name', v_applicant.full_name,
          'email', v_applicant.email,
          'phone_number', v_applicant.phone_number
        ),
        'permit_type', jsonb_build_object(
          'name', v_type.name,
          'application_code', v_type.application_code
        ),
        'business', to_jsonb(v_business) - 'owner_id'
      )
  where id = p_application;

  perform set_config('permitayo.status_remarks', '', true);

  perform public.write_audit_log(v_actor, 'application.submitted', 'permit_application', p_application,
    'Application submitted: ' || v_reference || '.');

  return v_reference;
end;
$$;

-- Cancel an application. The record is kept; status, timestamp, reason and the
-- cancelling user are recorded.
--   * The applicant who owns it may cancel a draft or a submitted application.
--   * BPLO personnel and administrators may cancel a submitted application, and
--     must give a reason.
create or replace function public.cancel_permit_application(p_application uuid, p_reason text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_role text := public.current_app_role();
  v_app public.permit_applications%rowtype;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_is_owner boolean;
  v_is_staff boolean;
begin
  if v_actor is null or v_role is null then
    raise exception 'Not authenticated.' using errcode = '42501';
  end if;
  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'Reason must be 500 characters or fewer.' using errcode = '22023';
  end if;

  select * into v_app from public.permit_applications where id = p_application for update;
  if not found then
    raise exception 'Application not found.' using errcode = 'P0002';
  end if;

  v_is_owner := v_role = 'applicant' and v_app.applicant_id = v_actor;
  v_is_staff := v_role in ('bplo_personnel', 'administrator') and v_app.application_status <> 'draft';

  if not v_is_owner and not v_is_staff then
    -- Do not reveal whether another applicant's application exists.
    raise exception 'Application not found.' using errcode = 'P0002';
  end if;
  if v_app.application_status not in ('draft', 'submitted') then
    raise exception 'This application can no longer be cancelled.';
  end if;
  if v_is_staff and not v_is_owner and v_reason is null then
    raise exception 'Give a reason for cancelling this application.';
  end if;

  perform set_config('permitayo.status_remarks',
    coalesce(v_reason, case when v_is_owner then 'Cancelled by the applicant.' else 'Cancelled by authorized personnel.' end),
    true);

  update public.permit_applications
  set application_status = 'cancelled',
      cancelled_at = now(),
      cancelled_by = v_actor,
      cancellation_reason = v_reason
  where id = p_application;

  perform set_config('permitayo.status_remarks', '', true);

  perform public.write_audit_log(v_actor, 'application.cancelled', 'permit_application', p_application,
    'Application cancelled' || coalesce(': ' || v_app.reference_number, ' (draft)') || '.');
end;
$$;

-- BPLO personnel and administrators set a business profile's record status.
create or replace function public.set_business_record_status(p_business uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.has_app_role(array['bplo_personnel', 'administrator']) then
    raise exception 'Only BPLO personnel or administrators can change a business record status.' using errcode = '42501';
  end if;
  if p_status is null or p_status not in ('pending_verification', 'active', 'inactive') then
    raise exception 'Invalid record status.' using errcode = '22023';
  end if;

  update public.business_establishments set record_status = p_status
  where id = p_business and record_status is distinct from p_status;

  if not found and not exists (select 1 from public.business_establishments where id = p_business) then
    raise exception 'Business profile not found.' using errcode = 'P0002';
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Table privileges
-- ---------------------------------------------------------------------------
revoke all on public.reference_counters from public, anon, authenticated;
revoke all on public.permit_types from public, anon, authenticated;
revoke all on public.business_establishments from public, anon, authenticated;
revoke all on public.permit_applications from public, anon, authenticated;
revoke all on public.application_status_history from public, anon, authenticated;

grant select, insert, update on public.permit_types to authenticated;

grant select on public.business_establishments to authenticated;
-- owner_id, business_reference_number, record_status and timestamps are not writable.
grant insert (
  registered_business_name, trade_name, business_description, business_type, ownership_type,
  business_category, business_email, business_contact_number, province, municipality, barangay,
  street_address, zip_code, owner_full_name, owner_email, owner_contact_number, nature_of_business,
  employee_count, estimated_capital, establishment_status, date_established
) on public.business_establishments to authenticated;
grant update (
  registered_business_name, trade_name, business_description, business_type, ownership_type,
  business_category, business_email, business_contact_number, province, municipality, barangay,
  street_address, zip_code, owner_full_name, owner_email, owner_contact_number, nature_of_business,
  employee_count, estimated_capital, establishment_status, date_established
) on public.business_establishments to authenticated;

grant select, delete on public.permit_applications to authenticated;
-- applicant_id, status, reference number, snapshot and timestamps are not writable.
grant insert (business_id, permit_type_id, business_name, business_address, nature_of_business, business_category, applicant_remarks)
  on public.permit_applications to authenticated;
grant update (business_id, permit_type_id, business_name, business_address, nature_of_business, business_category, applicant_remarks)
  on public.permit_applications to authenticated;

grant select on public.application_status_history to authenticated;

-- ---------------------------------------------------------------------------
-- Function privileges
-- ---------------------------------------------------------------------------
revoke all on function public.next_reference_number(text, integer) from public, anon, authenticated;
revoke all on function public.manila_year() from public, anon, authenticated;
revoke all on function public.assign_business_reference() from public, anon, authenticated;
revoke all on function public.guard_business_protected_columns() from public, anon, authenticated;
revoke all on function public.guard_application_insert() from public, anon, authenticated;
revoke all on function public.guard_application_update() from public, anon, authenticated;
revoke all on function public.guard_application_delete() from public, anon, authenticated;
revoke all on function public.guard_status_history_update() from public, anon, authenticated;
revoke all on function public.record_application_status() from public, anon, authenticated;
revoke all on function public.audit_business_change() from public, anon, authenticated;
revoke all on function public.audit_application_draft_delete() from public, anon, authenticated;
revoke all on function public.audit_permit_type_change() from public, anon, authenticated;
revoke all on function public.submit_permit_application(uuid) from public, anon, authenticated;
revoke all on function public.cancel_permit_application(uuid, text) from public, anon, authenticated;
revoke all on function public.set_business_record_status(uuid, text) from public, anon, authenticated;

-- Callable RPCs (each re-checks the caller inside).
grant execute on function public.submit_permit_application(uuid) to authenticated;
grant execute on function public.cancel_permit_application(uuid, text) to authenticated;
grant execute on function public.set_business_record_status(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.reference_counters enable row level security; -- no policies: no API access
alter table public.permit_types enable row level security;
alter table public.business_establishments enable row level security;
alter table public.permit_applications enable row level security;
alter table public.application_status_history enable row level security;

-- permit_types ----------------------------------------------------------------
-- Any active account can read active types; staff and administrators see all.
create policy permit_types_select
  on public.permit_types for select to authenticated
  using (
    (is_active and (select public.current_app_role()) is not null)
    or (select public.has_app_role(array['bplo_personnel', 'administrator']))
  );

create policy permit_types_insert_admin
  on public.permit_types for insert to authenticated
  with check ((select public.is_admin()));

create policy permit_types_update_admin
  on public.permit_types for update to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

-- business_establishments ---------------------------------------------------
create policy business_select_own
  on public.business_establishments for select to authenticated
  using (owner_id = (select auth.uid()));

create policy business_select_staff
  on public.business_establishments for select to authenticated
  using ((select public.has_app_role(array['bplo_personnel', 'administrator'])));

create policy business_insert_own
  on public.business_establishments for insert to authenticated
  with check (
    owner_id = (select auth.uid())
    and (select public.current_app_role()) = 'applicant'
  );

create policy business_update_own
  on public.business_establishments for update to authenticated
  using (
    owner_id = (select auth.uid())
    and (select public.current_app_role()) = 'applicant'
    and record_status <> 'inactive'
  )
  with check (owner_id = (select auth.uid()));

-- permit_applications -------------------------------------------------------
create policy applications_select_own
  on public.permit_applications for select to authenticated
  using (applicant_id = (select auth.uid()));

-- Drafts stay private to the applicant until they are submitted.
create policy applications_select_staff
  on public.permit_applications for select to authenticated
  using (
    application_status <> 'draft'
    and (select public.has_app_role(array['bplo_personnel', 'administrator']))
  );

create policy applications_insert_own
  on public.permit_applications for insert to authenticated
  with check (
    applicant_id = (select auth.uid())
    and application_status = 'draft'
    and (select public.current_app_role()) = 'applicant'
    and exists (
      select 1 from public.business_establishments b
      where b.id = business_id and b.owner_id = (select auth.uid()) and b.record_status <> 'inactive'
    )
    and exists (select 1 from public.permit_types t where t.id = permit_type_id and t.is_active)
  );

create policy applications_update_own_draft
  on public.permit_applications for update to authenticated
  using (
    applicant_id = (select auth.uid())
    and application_status = 'draft'
    and (select public.current_app_role()) = 'applicant'
  )
  with check (
    applicant_id = (select auth.uid())
    and application_status = 'draft'
    and exists (
      select 1 from public.business_establishments b
      where b.id = business_id and b.owner_id = (select auth.uid()) and b.record_status <> 'inactive'
    )
    and exists (select 1 from public.permit_types t where t.id = permit_type_id and t.is_active)
  );

create policy applications_delete_own_draft
  on public.permit_applications for delete to authenticated
  using (
    applicant_id = (select auth.uid())
    and application_status = 'draft'
    and (select public.current_app_role()) = 'applicant'
  );

-- application_status_history -------------------------------------------------
-- Visible exactly when the parent application is visible to the caller
-- (the subquery runs under the caller's own RLS on permit_applications).
create policy status_history_select
  on public.application_status_history for select to authenticated
  using (exists (select 1 from public.permit_applications a where a.id = application_id));

-- ====================================================================
-- 20261111000003_seed_permit_types.sql
-- ====================================================================
-- Permitayo, Phase 3: initial application types.
--
-- These are configurable records, not encoded procedures. No eligibility rule,
-- fee or requirement list is attached to them. Administrators can rename,
-- describe, deactivate or add types (UI for this arrives in a later phase; the
-- table already allows administrator writes under RLS).

insert into public.permit_types (name, description, application_code, is_active, sort_order)
values
  ('New Business Permit', 'Application for a business that does not yet hold a business permit from the municipality.', 'NEW', true, 10),
  ('Business Permit Renewal', 'Renewal of an existing business permit.', 'RENEWAL', true, 20),
  ('Business Information Amendment', 'Request to update information on record for an existing business permit.', 'AMENDMENT', true, 30)
on conflict (application_code) do nothing;

-- ====================================================================
-- 20261114000001_requirements_and_documents_schema.sql
-- ====================================================================
-- Permitayo, Phase 4: requirements and document management (schema).
-- Tables: permit_requirements, application_documents, document_review_history.
-- Security (grants, RLS, storage policies, definer functions) is in the next migration.
--
-- Files live in the EXISTING private Storage bucket 'permit-documents' (Phase 2),
-- under {applicant_id}/{application_id}/{requirement_id}/{generated_file_id}.{ext}.
-- No second bucket is created.

-- File types Permitayo can accept at all. Per-requirement lists must be a subset.
create or replace function public.allowed_document_mime_types()
returns text[]
language sql
immutable
set search_path = ''
as $$
  select array['application/pdf', 'image/jpeg', 'image/png']::text[]
$$;

-- ---------------------------------------------------------------------------
-- permit_requirements: configurable requirements per permit type
-- ---------------------------------------------------------------------------
create table public.permit_requirements (
  id uuid primary key default gen_random_uuid(),
  permit_type_id uuid not null references public.permit_types (id) on delete restrict,
  name text not null
    constraint permit_requirements_name_length check (char_length(btrim(name)) between 2 and 160),
  description text
    constraint permit_requirements_description_length check (description is null or char_length(description) <= 1000),
  applicant_instructions text
    constraint permit_requirements_instructions_length check (applicant_instructions is null or char_length(applicant_instructions) <= 1000),
  is_required boolean not null default true,
  accepted_file_types text[] not null default array['application/pdf', 'image/jpeg', 'image/png']::text[]
    constraint permit_requirements_file_types_valid check (
      cardinality(accepted_file_types) >= 1
      and accepted_file_types <@ public.allowed_document_mime_types()
    ),
  -- Bytes. Default 5 MB; the bucket itself caps every file at 10 MB.
  max_file_size integer not null default 5242880
    constraint permit_requirements_max_size_range check (max_file_size between 102400 and 10485760),
  display_order integer not null default 0
    constraint permit_requirements_display_order_range check (display_order between 0 and 10000),
  is_active boolean not null default true,
  -- Reserved for future conditional requirements (for example, only for certain
  -- ownership types). Not evaluated in Phase 4: every active requirement applies.
  conditions jsonb not null default '{}'::jsonb
    constraint permit_requirements_conditions_object check (jsonb_typeof(conditions) = 'object'),
  created_by uuid references public.profiles (id) on delete set null,
  updated_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index permit_requirements_type_order_idx on public.permit_requirements (permit_type_id, display_order, name);
create index permit_requirements_active_idx on public.permit_requirements (permit_type_id) where is_active;
create unique index permit_requirements_type_name_key on public.permit_requirements (permit_type_id, lower(name));

create trigger permit_requirements_set_updated_at
  before update on public.permit_requirements
  for each row execute function public.set_updated_at();

comment on table public.permit_requirements is
  'Document requirements per permit type, configured by BPLO personnel and administrators. Seeded rows are inactive samples.';

-- ---------------------------------------------------------------------------
-- application_documents: one row per uploaded file (every version is kept)
-- ---------------------------------------------------------------------------
create table public.application_documents (
  id uuid primary key default gen_random_uuid(),
  application_id uuid not null references public.permit_applications (id) on delete restrict,
  requirement_id uuid not null references public.permit_requirements (id) on delete restrict,
  applicant_id uuid not null references public.profiles (id) on delete restrict,
  original_filename text not null
    constraint application_documents_filename_length check (char_length(original_filename) between 1 and 255),
  -- Object name inside the 'permit-documents' bucket. Generated by the server.
  storage_path text not null,
  mime_type text not null
    constraint application_documents_mime_allowed check (mime_type = any (public.allowed_document_mime_types())),
  file_size integer not null
    constraint application_documents_size_range check (file_size between 1 and 10485760),
  submission_version integer not null
    constraint application_documents_version_positive check (submission_version >= 1),
  -- Only the newest version of a requirement's document is current.
  is_current boolean not null default true,
  document_status text not null default 'uploaded'
    constraint application_documents_status_allowed check (
      document_status in ('uploaded', 'under_review', 'accepted', 'needs_resubmission')
    ),
  -- Latest review, denormalised for the checklist. Full trail: document_review_history.
  review_comment text
    constraint application_documents_review_comment_length check (review_comment is null or char_length(review_comment) <= 1000),
  last_reviewed_by uuid references public.profiles (id) on delete set null,
  last_reviewed_at timestamptz,
  uploaded_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint application_documents_storage_path_key unique (storage_path),
  constraint application_documents_version_key unique (application_id, requirement_id, submission_version)
);

create unique index application_documents_one_current_idx
  on public.application_documents (application_id, requirement_id) where is_current;
create index application_documents_application_idx on public.application_documents (application_id, requirement_id, submission_version desc);
create index application_documents_applicant_idx on public.application_documents (applicant_id);
create index application_documents_status_idx on public.application_documents (document_status) where is_current;
create index application_documents_requirement_idx on public.application_documents (requirement_id);

create trigger application_documents_set_updated_at
  before update on public.application_documents
  for each row execute function public.set_updated_at();

comment on table public.application_documents is
  'Uploaded supporting documents. Written only by definer functions; replaced versions are kept with is_current = false.';

-- ---------------------------------------------------------------------------
-- document_review_history: append-only manual review trail
-- ---------------------------------------------------------------------------
create table public.document_review_history (
  id uuid primary key default gen_random_uuid(),
  application_document_id uuid not null references public.application_documents (id) on delete restrict,
  reviewed_by uuid references public.profiles (id) on delete set null,
  previous_status text not null,
  new_status text not null
    constraint document_review_history_status_allowed check (new_status in ('under_review', 'accepted', 'needs_resubmission')),
  review_comment text
    constraint document_review_history_comment_length check (review_comment is null or char_length(review_comment) <= 1000),
  created_at timestamptz not null default now()
);

create index document_review_history_document_idx on public.document_review_history (application_document_id, created_at);

-- ====================================================================
-- 20261114000002_requirements_and_documents_security.sql
-- ====================================================================
-- Permitayo, Phase 4: security for requirements and documents.
--
--   * permit_requirements: written by BPLO personnel and administrators under RLS;
--     created_by / updated_by are set by a trigger, never by the client; every
--     change is audited.
--   * application_documents and document_review_history: NO insert/update grants.
--     Rows are written only by register_application_document() and
--     review_application_document(), which re-check the caller with auth.uid().
--   * Storage ('permit-documents', private): an applicant can create an object
--     only at {own id}/{own application}/{requirement}/{uuid}.{pdf|jpg|png} and
--     only when that upload is currently allowed. BPLO personnel can read objects
--     that belong to submitted applications. Nobody can update objects; an
--     applicant can delete only their own objects that were never registered
--     (cleanup after a failed upload).

-- ---------------------------------------------------------------------------
-- permit_requirements: guard + audit
-- ---------------------------------------------------------------------------
create or replace function public.guard_permit_requirement()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' then
      new.created_by := (select auth.uid());
      new.updated_by := (select auth.uid());
      new.conditions := '{}'::jsonb;
    else
      if new.permit_type_id is distinct from old.permit_type_id
         or new.created_by is distinct from old.created_by
         or new.created_at is distinct from old.created_at
         or new.conditions is distinct from old.conditions then
        raise exception 'This requirement field cannot be changed.' using errcode = '42501';
      end if;
      new.updated_by := (select auth.uid());
    end if;
  end if;
  return new;
end;
$$;

create trigger permit_requirements_guard
  before insert or update on public.permit_requirements
  for each row execute function public.guard_permit_requirement();

create or replace function public.audit_permit_requirement_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
begin
  if tg_op = 'INSERT' then
    perform public.write_audit_log(v_actor, 'requirement.created', 'permit_requirement', new.id,
      'Requirement created: ' || new.name || '.');
  elsif new.is_active is distinct from old.is_active then
    perform public.write_audit_log(v_actor,
      case when new.is_active then 'requirement.activated' else 'requirement.deactivated' end,
      'permit_requirement', new.id,
      'Requirement ' || case when new.is_active then 'activated' else 'deactivated' end || ': ' || new.name || '.');
  else
    perform public.write_audit_log(v_actor, 'requirement.updated', 'permit_requirement', new.id,
      'Requirement updated: ' || new.name || '.');
  end if;
  return new;
end;
$$;

create trigger permit_requirements_audit_change
  after insert or update on public.permit_requirements
  for each row execute function public.audit_permit_requirement_change();

-- Review history is append-only for everyone.
create or replace function public.guard_document_review_history()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'Document review history cannot be changed.' using errcode = '42501';
end;
$$;

create trigger document_review_history_append_only
  before update or delete on public.document_review_history
  for each row execute function public.guard_document_review_history();

-- ---------------------------------------------------------------------------
-- Upload eligibility (shared by the storage policy and the register function)
--   draft application      -> upload or replace any active requirement
--   submitted application  -> upload a requirement that has no document yet,
--                             or replace one marked needs_resubmission
--   cancelled application  -> nothing
-- ---------------------------------------------------------------------------
create or replace function public.document_upload_allowed(p_application uuid, p_requirement uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select
      a.application_status in ('draft', 'submitted')
      and (
        a.application_status = 'draft'
        or not exists (
          select 1 from public.application_documents d
          where d.application_id = a.id and d.requirement_id = r.id and d.is_current
        )
        or exists (
          select 1 from public.application_documents d
          where d.application_id = a.id and d.requirement_id = r.id and d.is_current
            and d.document_status = 'needs_resubmission'
        )
      )
    from public.permit_applications a
    join public.permit_requirements r on r.permit_type_id = a.permit_type_id and r.id = p_requirement and r.is_active
    where a.id = p_application
      and a.applicant_id = (select auth.uid())
      and public.current_app_role() = 'applicant'
  ), false)
$$;

-- Storage object name -> may the caller create it?
create or replace function public.storage_document_upload_allowed(p_name text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_parts text[];
begin
  if p_name is null
     or p_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(pdf|jpg|png)$' then
    return false;
  end if;
  v_parts := string_to_array(p_name, '/');
  if v_parts[1] <> (select auth.uid())::text then
    return false;
  end if;
  return public.document_upload_allowed(v_parts[2]::uuid, v_parts[3]::uuid);
end;
$$;

create or replace function public.document_object_registered(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.application_documents d where d.storage_path = p_name)
$$;

-- BPLO personnel may read files of non-draft applications.
create or replace function public.staff_can_read_document_object(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.current_app_role() = 'bplo_personnel'
    and exists (
      select 1
      from public.application_documents d
      join public.permit_applications a on a.id = d.application_id
      where d.storage_path = p_name and a.application_status <> 'draft'
    )
$$;

-- ---------------------------------------------------------------------------
-- register_application_document: record an object the applicant uploaded.
-- Size and type are read from Storage's own metadata, not from the client.
-- ---------------------------------------------------------------------------
create or replace function public.register_application_document(
  p_application uuid,
  p_requirement uuid,
  p_storage_path text,
  p_original_filename text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_app public.permit_applications%rowtype;
  v_req public.permit_requirements%rowtype;
  v_current public.application_documents%rowtype;
  v_size bigint;
  v_mime text;
  v_name text := btrim(coalesce(p_original_filename, ''));
  v_version integer;
  v_id uuid;
  v_ext text;
begin
  if v_actor is null or public.current_app_role() is distinct from 'applicant' then
    raise exception 'Only applicants can upload documents.' using errcode = '42501';
  end if;

  select * into v_app from public.permit_applications where id = p_application for update;
  if not found or v_app.applicant_id <> v_actor then
    raise exception 'Application not found.' using errcode = 'P0002';
  end if;

  select * into v_req from public.permit_requirements where id = p_requirement;
  if not found or v_req.permit_type_id <> v_app.permit_type_id or not v_req.is_active then
    raise exception 'That requirement does not apply to this application.';
  end if;

  if not public.document_upload_allowed(p_application, p_requirement) then
    if v_app.application_status = 'cancelled' then
      raise exception 'This application was cancelled, so documents can no longer be uploaded.';
    end if;
    raise exception 'This document cannot be replaced now. After submission, you can only replace documents the BPLO marked as needing resubmission.';
  end if;

  -- The object must sit in this applicant/application/requirement folder.
  if p_storage_path is null
     or split_part(p_storage_path, '/', 1) <> v_actor::text
     or split_part(p_storage_path, '/', 2) <> p_application::text
     or split_part(p_storage_path, '/', 3) <> p_requirement::text then
    raise exception 'Invalid upload location.' using errcode = '42501';
  end if;

  select (o.metadata ->> 'size')::bigint, lower(o.metadata ->> 'mimetype')
  into v_size, v_mime
  from storage.objects o
  where o.bucket_id = 'permit-documents' and o.name = p_storage_path;
  if not found then
    raise exception 'The uploaded file was not found. Please upload it again.';
  end if;
  if v_mime = 'image/jpg' then v_mime := 'image/jpeg'; end if;

  v_ext := lower(substring(p_storage_path from '\.([a-z]+)$'));
  if v_mime is null or not (v_mime = any (v_req.accepted_file_types))
     or (v_ext = 'pdf' and v_mime <> 'application/pdf')
     or (v_ext = 'jpg' and v_mime <> 'image/jpeg')
     or (v_ext = 'png' and v_mime <> 'image/png') then
    raise exception 'That file type is not accepted for this requirement.';
  end if;
  if v_size is null or v_size < 1 then
    raise exception 'The uploaded file is empty.';
  end if;
  if v_size > v_req.max_file_size then
    raise exception 'The file is larger than the % MB limit for this requirement.', round(v_req.max_file_size / 1048576.0, 1);
  end if;

  if public.document_object_registered(p_storage_path) then
    raise exception 'This file was already recorded.';
  end if;

  -- Keep a safe display name only (no path separators or control characters).
  v_name := regexp_replace(v_name, '[[:cntrl:]/\\]', '_', 'g');
  if v_name = '' then v_name := 'document'; end if;
  v_name := left(v_name, 255);

  select * into v_current from public.application_documents
  where application_id = p_application and requirement_id = p_requirement and is_current
  for update;

  select coalesce(max(submission_version), 0) + 1 into v_version
  from public.application_documents
  where application_id = p_application and requirement_id = p_requirement;

  if v_current.id is not null then
    update public.application_documents set is_current = false where id = v_current.id;
  end if;

  insert into public.application_documents (
    application_id, requirement_id, applicant_id, original_filename, storage_path,
    mime_type, file_size, submission_version, is_current, document_status
  )
  values (
    p_application, p_requirement, v_actor, v_name, p_storage_path,
    v_mime, v_size::integer, v_version, true, 'uploaded'
  )
  returning id into v_id;

  perform public.write_audit_log(v_actor,
    case when v_current.id is null then 'document.uploaded' else 'document.replaced' end,
    'application_document', v_id,
    case when v_current.id is null
      then 'Document uploaded for requirement "' || v_req.name || '" (version ' || v_version || ').'
      else 'Document replaced for requirement "' || v_req.name || '" (version ' || v_version || ').'
    end);

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- review_application_document: manual review by BPLO personnel only.
-- ---------------------------------------------------------------------------
create or replace function public.review_application_document(
  p_document uuid,
  p_status text,
  p_comment text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := (select auth.uid());
  v_doc public.application_documents%rowtype;
  v_app_status text;
  v_req_name text;
  v_comment text := nullif(btrim(coalesce(p_comment, '')), '');
begin
  if v_actor is null or public.current_app_role() is distinct from 'bplo_personnel' then
    raise exception 'Only BPLO personnel can review documents.' using errcode = '42501';
  end if;
  if p_status is null or p_status not in ('under_review', 'accepted', 'needs_resubmission') then
    raise exception 'Invalid review status.' using errcode = '22023';
  end if;
  if v_comment is not null and char_length(v_comment) > 1000 then
    raise exception 'Comments must be 1,000 characters or fewer.' using errcode = '22023';
  end if;
  if p_status = 'needs_resubmission' and v_comment is null then
    raise exception 'Explain what the applicant needs to fix before asking for a resubmission.';
  end if;

  select * into v_doc from public.application_documents where id = p_document for update;
  if not found then
    raise exception 'Document not found.' using errcode = 'P0002';
  end if;
  select a.application_status into v_app_status from public.permit_applications a where a.id = v_doc.application_id;
  if v_app_status is distinct from 'submitted' then
    -- Drafts are private; cancelled applications are closed.
    raise exception 'Only documents of submitted applications can be reviewed.';
  end if;
  if not v_doc.is_current then
    raise exception 'This is an older version. Review the current document instead.';
  end if;
  if v_doc.document_status = p_status and v_comment is null then
    raise exception 'The document already has that status.';
  end if;

  update public.application_documents
  set document_status = p_status,
      review_comment = v_comment,
      last_reviewed_by = v_actor,
      last_reviewed_at = now()
  where id = p_document;

  insert into public.document_review_history (application_document_id, reviewed_by, previous_status, new_status, review_comment)
  values (p_document, v_actor, v_doc.document_status, p_status, v_comment);

  select name into v_req_name from public.permit_requirements where id = v_doc.requirement_id;
  perform public.write_audit_log(v_actor,
    case p_status
      when 'needs_resubmission' then 'document.resubmission_requested'
      when 'accepted' then 'document.accepted'
      else 'document.review_started'
    end,
    'application_document', p_document,
    'Document for requirement "' || coalesce(v_req_name, 'unknown') || '" (version ' || v_doc.submission_version
      || ') marked ' || replace(p_status, '_', ' ') || '.');
end;
$$;

-- ---------------------------------------------------------------------------
-- Table privileges
-- ---------------------------------------------------------------------------
revoke all on public.permit_requirements from public, anon, authenticated;
revoke all on public.application_documents from public, anon, authenticated;
revoke all on public.document_review_history from public, anon, authenticated;

grant select on public.permit_requirements to authenticated;
grant insert (permit_type_id, name, description, applicant_instructions, is_required, accepted_file_types, max_file_size, display_order, is_active)
  on public.permit_requirements to authenticated;
grant update (name, description, applicant_instructions, is_required, accepted_file_types, max_file_size, display_order, is_active)
  on public.permit_requirements to authenticated;

grant select on public.application_documents to authenticated;
grant select on public.document_review_history to authenticated;

-- ---------------------------------------------------------------------------
-- Function privileges
-- ---------------------------------------------------------------------------
revoke all on function public.allowed_document_mime_types() from public, anon, authenticated;
revoke all on function public.guard_permit_requirement() from public, anon, authenticated;
revoke all on function public.audit_permit_requirement_change() from public, anon, authenticated;
revoke all on function public.guard_document_review_history() from public, anon, authenticated;
revoke all on function public.document_upload_allowed(uuid, uuid) from public, anon, authenticated;
revoke all on function public.storage_document_upload_allowed(text) from public, anon, authenticated;
revoke all on function public.document_object_registered(text) from public, anon, authenticated;
revoke all on function public.staff_can_read_document_object(text) from public, anon, authenticated;
revoke all on function public.register_application_document(uuid, uuid, text, text) from public, anon, authenticated;
revoke all on function public.review_application_document(uuid, text, text) from public, anon, authenticated;

-- Used by CHECK constraints and policies evaluated for signed-in users.
grant execute on function public.allowed_document_mime_types() to authenticated;
grant execute on function public.document_upload_allowed(uuid, uuid) to authenticated;
grant execute on function public.storage_document_upload_allowed(text) to authenticated;
grant execute on function public.document_object_registered(text) to authenticated;
grant execute on function public.staff_can_read_document_object(text) to authenticated;
-- Callable RPCs (each re-checks the caller inside).
grant execute on function public.register_application_document(uuid, uuid, text, text) to authenticated;
grant execute on function public.review_application_document(uuid, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.permit_requirements enable row level security;
alter table public.application_documents enable row level security;
alter table public.document_review_history enable row level security;

-- permit_requirements -------------------------------------------------------
create policy permit_requirements_select_staff
  on public.permit_requirements for select to authenticated
  using ((select public.has_app_role(array['bplo_personnel', 'administrator'])));

-- Applicants: active requirements of permit types they have applications for,
-- plus any requirement they have already uploaded a document for.
create policy permit_requirements_select_applicant
  on public.permit_requirements for select to authenticated
  using (
    (select public.current_app_role()) = 'applicant'
    and (
      (is_active and exists (
        select 1 from public.permit_applications a
        where a.permit_type_id = permit_requirements.permit_type_id and a.applicant_id = (select auth.uid())
      ))
      or exists (
        select 1 from public.application_documents d
        where d.requirement_id = permit_requirements.id and d.applicant_id = (select auth.uid())
      )
    )
  );

create policy permit_requirements_insert_staff
  on public.permit_requirements for insert to authenticated
  with check ((select public.has_app_role(array['bplo_personnel', 'administrator'])));

create policy permit_requirements_update_staff
  on public.permit_requirements for update to authenticated
  using ((select public.has_app_role(array['bplo_personnel', 'administrator'])))
  with check ((select public.has_app_role(array['bplo_personnel', 'administrator'])));

-- application_documents -----------------------------------------------------
create policy application_documents_select_own
  on public.application_documents for select to authenticated
  using (applicant_id = (select auth.uid()));

create policy application_documents_select_bplo
  on public.application_documents for select to authenticated
  using (
    (select public.current_app_role()) = 'bplo_personnel'
    and exists (
      select 1 from public.permit_applications a
      where a.id = application_documents.application_id and a.application_status <> 'draft'
    )
  );

-- document_review_history ---------------------------------------------------
create policy document_review_history_select
  on public.document_review_history for select to authenticated
  using (exists (
    select 1 from public.application_documents d where d.id = document_review_history.application_document_id
  ));

-- ---------------------------------------------------------------------------
-- Storage policies for the existing private 'permit-documents' bucket.
-- Replaces the broad Phase 2 insert policy (any file in the applicant's folder).
-- ---------------------------------------------------------------------------
drop policy if exists "Applicants upload to own folder" on storage.objects;

create policy "Applicants upload allowed application documents"
  on storage.objects for insert to authenticated
  with check (
    bucket_id = 'permit-documents'
    and (select public.storage_document_upload_allowed(name))
  );

-- "Applicants read own folder" (Phase 2) stays as is.

create policy "BPLO personnel read submitted application documents"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'permit-documents'
    and (select public.staff_can_read_document_object(name))
  );

create policy "Applicants remove unregistered uploads"
  on storage.objects for delete to authenticated
  using (
    bucket_id = 'permit-documents'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and (select public.current_app_role()) = 'applicant'
    and not (select public.document_object_registered(name))
  );

-- ====================================================================
-- 20261114000003_seed_sample_requirements.sql
-- ====================================================================
-- Permitayo, Phase 4: SAMPLE requirements.
--
-- These are placeholders, NOT the official requirements of the Municipality of
-- Rosario. They are inserted INACTIVE, so applicants do not see them. BPLO
-- personnel should replace the names and instructions with the official list
-- (Dashboard > BPLO > Permit Requirements), then activate them, or add new ones.

insert into public.permit_requirements
  (permit_type_id, name, description, applicant_instructions, is_required, accepted_file_types, max_file_size, display_order, is_active)
select t.id, s.name, s.description, s.instructions, s.is_required,
       array['application/pdf', 'image/jpeg', 'image/png']::text[], 5242880, s.display_order, false
from public.permit_types t
join (values
  ('NEW', 'Sample: Proof of business name registration',
   'Placeholder. Replace with the official BPLO requirement before activating.',
   'Upload a clear scan or photo of the whole document.', true, 10),
  ('NEW', 'Sample: Valid government-issued ID of the owner',
   'Placeholder. Replace with the official BPLO requirement before activating.',
   'Upload the front and back on one page if possible.', true, 20),
  ('NEW', 'Sample: Proof of business location',
   'Placeholder. Replace with the official BPLO requirement before activating.',
   'For example, a lease contract or proof of ownership, if this applies to your business.', false, 30),
  ('RENEWAL', 'Sample: Previous business permit',
   'Placeholder. Replace with the official BPLO requirement before activating.',
   'Upload a clear scan or photo of your most recent permit.', true, 10),
  ('RENEWAL', 'Sample: Valid government-issued ID of the owner',
   'Placeholder. Replace with the official BPLO requirement before activating.',
   'Upload the front and back on one page if possible.', true, 20),
  ('AMENDMENT', 'Sample: Supporting document for the requested change',
   'Placeholder. Replace with the official BPLO requirement before activating.',
   'Upload the document that shows the new information.', true, 10)
) as s(code, name, description, instructions, is_required, display_order)
  on s.code = t.application_code
on conflict do nothing;
